async function hydrateSources(){try{let j=await api('/api/health',{},15000);if(j.build!==BUILD)throw Error('Backend sai phiên bản');SOURCE_ORDER=Array.isArray(j.sourceOrder)?j.sourceOrder:[];ACTIVE_FAMILY_COUNT=Number(j.activeFamilyCount||0);PROBE_FAMILY_COUNT=Number(j.probeFamilyCount||0);QUARANTINE_FAMILY_COUNT=Number(j.quarantineFamilyCount||0);STATIC_REMOVED_COUNT=Number(j.staticRemovedCount||0);ENABLED_FAMILY_COUNT=Number(j.enabledFamilyCount||SOURCE_ORDER.length||0);TOTAL_FAMILY_COUNT=Number(j.totalFamilyCount||0);CONFIGURED_SITE_COUNT=Number(j.configuredSiteCount||0);INDEPENDENT_FAMILY_COUNT=Number(j.independentFamilyCount||TOTAL_FAMILY_COUNT||0);FALLBACK_ENDPOINT_COUNT=Number(j.fallbackEndpointCount||0);TARGET_FALLBACK_ENDPOINT_COUNT=Number(j.targetFallbackEndpointCount||50);RESEARCH_REGISTRY_COUNT=Number(j.researchRegistryCount||132);RESEARCH_PENDING_READER_COUNT=Number(j.researchPendingReaderCount||0);RUNTIME_READER_COVERAGE_COUNT=Number(j.runtimeReaderCoverageCount||0);DEDICATED_READER_COUNT=Number(j.dedicatedReaderCount||0);GENERIC_READER_COUNT=Number(j.genericReaderCount||0);RUNTIME_MISSING_READER_COUNT=Number(j.runtimeMissingReaderCount||0);if(!SOURCE_ORDER.length||ENABLED_FAMILY_COUNT!==SOURCE_ORDER.length||RUNTIME_READER_COVERAGE_COUNT!==SOURCE_ORDER.length)throw Error('Backend chưa nạp đủ registry/reader');SOURCES_READY=true;state.sourceHealth={...state.sourceHealth,total:ENABLED_FAMILY_COUNT,quarantine:QUARANTINE_FAMILY_COUNT};state.siteHealth={...state.siteHealth,total:CONFIGURED_SITE_COUNT};renderSources();return true}catch(e){SOURCES_READY=false;SOURCE_ORDER=[];ENABLED_FAMILY_COUNT=0;TOTAL_FAMILY_COUNT=0;RUNTIME_READER_COVERAGE_COUNT=0;renderSources();setStatus('status','❌ Backend chưa khởi tạo: '+(e?.message||e),false);return false}}

let CLOUD_KEYS={};
