function saveKeyState(z){CLOUD_KEYS=z||{}}
async function hydrateKeyProviders(){try{const [j,k]=await Promise.all([api('/api/key/providers',{},15000),api('/api/background/keys/status',{},15000)]);if(j.build!==BUILD||!Array.isArray(j.providers)||j.providers.length!==2)throw Error('Danh sách KEY API chưa đúng 2 nguồn');state.keyProviders=j.providers;CLOUD_KEYS=Object.fromEntries((k.providers||[]).map(x=>[x.id,x]));renderKeys();return true}catch(e){state.keyProviders=[];renderKeys('❌ Không nạp được 2 KEY cloud: '+(e?.message||e));return false}}
function keyStats(){const configured=state.keyProviders.filter(p=>CLOUD_KEYS[p.id]?.configured).length,verified=state.keyProviders.filter(p=>CLOUD_KEYS[p.id]?.verified).length,usable=state.keyProviders.filter(p=>CLOUD_KEYS[p.id]?.usable).length;return{configured,verified,usable}}
function renderKeys(error=''){const box=$('keyProviders'),sum=$('keySummary');if(!box||!sum)return;const st=keyStats();state.keyHealth={...state.keyHealth,...st};sum.className='status'+(st.usable?' ok':'');sum.textContent=error||`🔐 CLOUD KEY dùng chung • đã lưu ${st.configured}/2 • LIVE đạt chuẩn ${st.usable}/2. Key không được trả lại trình duyệt.`;if(!state.keyProviders.length){box.innerHTML='<div class="src warn">Đang nạp 2 KEY cloud…</div>';return}box.innerHTML=state.keyProviders.map(p=>{const z=CLOUD_KEYS[p.id]||{},label=z.usable?`✅ LIVE • ${z.both||0} trận • ${z.books||0} book`:z.configured&&z.verified?'⚠️ Đã test nhưng lượt này chưa đủ AH+T/X':z.configured?'ĐÃ LƯU CLOUD • CHƯA TEST':'CHƯA CÓ KEY';return `<div class="keyrow ${z.usable?'ok':z.configured?'warn':''}"><div class="keyhead"><b>${esc(p.id)} • ${esc(p.name)}</b><span class="keystatus">${esc(label)}</span></div><div class="small">${esc(p.note||'')}</div><div class="keyactions"><input class="keyinput" type="password" autocomplete="off" spellcheck="false" data-keyinput="${esc(p.id)}" value="" placeholder="${z.configured?'Dán key mới để thay key cloud':'Dán API key'}"><button class="secondary keytest" data-keytest="${esc(p.id)}">TEST KEY CLOUD</button><a class="keylink" href="${esc(p.signup)}" target="_blank" rel="noopener">LẤY KEY</a></div>${z.note?`<div class="small keynote">${esc(z.note)}</div>`:''}</div>`}).join('');box.querySelectorAll('[data-keytest]').forEach(el=>el.addEventListener('click',()=>testKeyProvider(el.dataset.keytest,el)))}
async function saveAllKeys(hide=false){const keys={};for(const el of document.querySelectorAll('[data-keyinput]'))if(el.value.trim())keys[el.dataset.keyinput]=el.value.trim();if(!Object.keys(keys).length){setStatus('keySummary','Không có key mới để lưu; key cloud hiện tại vẫn được giữ.',true);return}await api('/api/background/keys/save',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({keys})},20000);await hydrateKeyProviders();setStatus('keySummary','✅ Đã lưu key lên kho cloud dùng chung. Ô nhập đã xóa để không lộ key.',true);if(hide){const box=$('keyBody'),b=$('toggleKeys');box?.classList.add('hidden');if(b)b.textContent='HIỆN KEY'}}
async function testKeyProvider(id,button){button.disabled=true;button.textContent='ĐANG TEST…';try{const el=document.querySelector(`[data-keyinput="${id}"]`);if(el?.value.trim())await api('/api/background/keys/save',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({keys:{[id]:el.value.trim()}})},20000);const j=await api('/api/background/keys/test',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({provider:id})},90000);await hydrateKeyProviders();setStatus('keySummary',j.usable?'✅ KEY cloud LIVE và có AH + T/X.':'⚠️ Key đã gọi được nhưng lượt test chưa có trận đủ AH + T/X.',j.usable===true)}catch(e){setStatus('keySummary','❌ TEST KEY cloud: '+e.message,false)}finally{button.disabled=false;button.textContent='TEST KEY CLOUD'}}
