async function uploadLedgerOnce(){const ack=new Set([...LEDGER_ACK,...[...(CLOUD_AUTO?.pending||[]),...(CLOUD_AUTO?.history||[])].map(ledgerKey)]),rows=pendingLedger().filter(p=>!ack.has(ledgerKey(p)));for(let i=0;i<rows.length;i+=100){const j=await api('/api/background/sync-ledger',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({predictions:rows.slice(i,i+100)})},30000);if(j.ok!==true)throw Error(j.error||'Chưa đồng bộ đủ sổ kèo');for(const key of j.acknowledged||[])LEDGER_ACK.add(key)}}
