function predKey(p){return `${teamKey(p?.home)}|${teamKey(p?.away)}|${Math.round(Date.parse(p?.date||0)/60000)}`}
function reserveLedger(){try{let x=JSON.parse(localStorage.getItem(RESERVE)||'[]');return Array.isArray(x)?x:[]}catch{return[]}}
function saveReserve(rows){try{const now=Date.now(),seen=new Set(),out=[];for(const p of rows||[]){const t=Date.parse(p?.date);if(!Number.isFinite(t)||t<=now||t>now+30*3600e3)continue;const k=predKey(p);if(seen.has(k))continue;seen.add(k);out.push(p);if(out.length>=100)break}localStorage.setItem(RESERVE,JSON.stringify(out))}catch{}}
function fillFromReserve(basePred=state.pred,now=Date.now()){const keep=(basePred||[]).filter(p=>Date.parse(p.date)>now&&Date.parse(p.date)<=now+86400000),seen=new Set(keep.map(predKey)),reserve=reserveLedger().filter(p=>Date.parse(p.date)>now&&Date.parse(p.date)<=now+86400000).sort((a,b)=>Date.parse(a.date)-Date.parse(b.date));for(const p of reserve){if(keep.length>=20)break;const k=predKey(p);if(!seen.has(k)){seen.add(k);keep.push(p)}}keep.sort((a,b)=>Date.parse(a.date)-Date.parse(b.date));return keep.slice(0,20)}
function autoMeta(){try{const z=JSON.parse(localStorage.getItem(AUTO_META)||'{}');return z&&typeof z==='object'?z:{}}catch{return{}}}
function saveAutoMeta(z){try{localStorage.setItem(AUTO_META,JSON.stringify(z))}catch{}}
function bootstrapAutoMeta(){const z=autoMeta();if(!Number(z.lastCycleAt)){const ledger=pendingLedger(),last=ledger.reduce((m,x)=>Math.max(m,Number(x.savedAt||0)),0);z.lastCycleAt=last||Date.now();z.lastSuccessAt=last||0;z.retryAt=0;saveAutoMeta(z)}return z}
function markScanAttempt(trigger){const z=bootstrapAutoMeta(),now=Date.now();z.lastAttemptAt=now;if(trigger==='auto')z.lastAutoAttemptAt=now;else z.lastManualAttemptAt=now;saveAutoMeta(z);renderAutoStatus();return z}
function markScanSuccess(trigger){const z=bootstrapAutoMeta(),now=Date.now();z.lastCycleAt=now;z.lastSuccessAt=now;z.retryAt=0;if(trigger==='auto')z.lastAutoAt=now;else z.lastManualAt=now;saveAutoMeta(z);renderAutoStatus();return z}
function markScanFailure(trigger){const z=bootstrapAutoMeta(),now=Date.now();z.lastFailureAt=now;z.retryAt=now+AUTO_RETRY_MS;if(trigger==='auto')z.lastAutoFailureAt=now;else z.lastManualFailureAt=now;saveAutoMeta(z);renderAutoStatus();return z}
function nextAutoMs(){const z=bootstrapAutoMeta(),now=Date.now(),due=Number(z.lastCycleAt||0)+AUTO_FETCH_MS;if(due>now)return due-now;const retry=Number(z.retryAt||0);return retry>now?retry-now:0}
function fmtRemain(ms){if(ms<=0)return'đến hạn';const h=Math.floor(ms/3600000),m=Math.ceil((ms-h*3600000)/60000);return h?`${h}g ${m}p`:`${m}p`}
function methodSummary(type){const lab=methodLab(),rank=rankedMethods(type),mature=rank.filter(x=>x.n>=20&&eligibleMethod(x.id,lab[type])),champ=lab.champion?.[type]||'book_weight',top=(mature.length?rank:rank.slice(0,3)).slice(0,3);return `${type}: ${METHOD_NAMES[champ]||champ}${mature.length?` • TOP ${top.map(x=>`${METHOD_NAMES[x.id]||x.id} ${(x.score*100).toFixed(1)} (${x.n})`).join(' / ')}`:' • chưa đủ 20 mẫu đã chấm, đang dùng Book Reliability'}`}
function renderAutoStatus(extra=''){const e=$('autoLearn');if(!e)return;const z=bootstrapAutoMeta(),cm=CLOUD_AUTO?.meta||null,pm=CLOUD_AUTO?.poolMeta||null,nextAt=Number(cm?.nextFetchAt||0),due=cm?fmtRemain(nextAt-Date.now()):fmtRemain(nextAutoMs()),poolLast=Number(cm?.lastPoolScanSuccessAt||cm?.lastAutoAt||0),last=poolLast?vnTime(poolLast):(z.lastSuccessAt?vnTime(z.lastSuccessAt):'chưa có'),cache=pm?.rowCount?`CACHE 12h→12h: ${Number(pm.rowCount)} row • ${pm.complete===true?'đủ lượt nguồn':'đang tích lũy'} • cập nhật ${pm.updatedAt?vnTime(pm.updatedAt):'chưa rõ'}. `:'CACHE 12h→12h: chưa có dữ liệu. ';e.textContent=`AUTO NỀN CLOUD • máy/tắt tab vẫn chạy • quét pool mỗi 4 giờ; khung 12:00–13:00 VN tự kích hoạt/đẩy nhanh lượt quét • lần pool hoàn tất gần nhất ${last} • lần kế tiếp ${due}.
${cache}
${methodSummary('AH')}
${methodSummary('OU')}
${cm?.scanActive?`Cloud đang quét ${cm.scanMode||'background'} ${cm.scanCursor||0}/${cm.activeSourceCount||0} nguồn; từng nguồn được chờ hết budget trước khi chuyển tiếp. `:''}${cm?.lastError?`Lần gần nhất: ${cm.lastError}. `:''}Bấm LẤY 20/LẤY TRẬN LỚN ưu tiên đọc cache, không reset lượt quét nền. ${extra}`.trim()}
const SHARED_POOL_TTL_MS=4*3600e3+20*60e3;
function sharedPoolMetaFresh(meta){const m=meta||{};return Number(m.rowCount||0)>0&&Number(m.updatedAt||0)>0&&Date.now()-Number(m.updatedAt)<=SHARED_POOL_TTL_MS}
function sharedPoolCovers(meta,ts=Date.now()){const m=meta||{},from=Number(m.from||0),to=Number(m.to||0);return Number(m.rowCount||0)>0&&from>0&&to>from&&ts>=from&&ts<=to}
async function loadSharedPoolFromCloud(meta=CLOUD_AUTO?.poolMeta,{allowStale=false}={}){if(!(allowStale?sharedPoolCovers(meta):sharedPoolMetaFresh(meta)))return false;const updatedAt=Number(meta?.updatedAt||0);if(state.rows.length&&Number(state.scanFinishedAt||0)===updatedAt)return true;const j=await api('/api/background/pool',{},60000);if(j.build!==BUILD||!Array.isArray(j.rows))throw Error('Pool cloud không hợp lệ');state.rows=mergeRows(j.rows);state.ts=Number(j.poolMeta?.from||Date.now());state.scanComplete=j.poolMeta?.complete===true;state.scanFinishedAt=Number(j.poolMeta?.updatedAt||0);CLOUD_AUTO=CLOUD_AUTO||{};CLOUD_AUTO.poolMeta=j.poolMeta||meta;return state.rows.length>0}
async function kickCloudRefresh(reason='cache-refresh'){try{const j=await api('/api/background/ensure-scan',{method:'POST',headers:{'x-scan-reason':reason}},20000);CLOUD_AUTO=CLOUD_AUTO||{};CLOUD_AUTO.meta={...(CLOUD_AUTO.meta||{}),...(j.meta||{})};CLOUD_AUTO.poolMeta=j.poolMeta||CLOUD_AUTO.poolMeta;renderAutoStatus('Đã giao cloud tiếp tục làm mới cache; không reset dữ liệu đang có.');return j}catch(e){renderAutoStatus('Cache vẫn dùng được; chưa kích hoạt được lượt làm mới nền: '+e.message);return null}}
async function saveSharedPoolToCloud(rows,{from=Date.now(),complete=false,sourceHealth=null,origin='manual'}={}){const cleanRows=mergeRows(rows||[]);if(!cleanRows.length)return null;const j=await api('/api/background/pool',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({rows:cleanRows,from,to:from+86400000,complete:complete===true,sourceHealth,checkedSources:Number(sourceHealth?.checked||0),totalSources:Number(sourceHealth?.total||ENABLED_FAMILY_COUNT||SOURCE_ORDER.length||95),origin})},90000);if(j.ok===false)throw Error(j.error||'Không lưu được pool cloud');CLOUD_AUTO=CLOUD_AUTO||{};CLOUD_AUTO.poolMeta=j.poolMeta||CLOUD_AUTO.poolMeta;state.scanFinishedAt=Number(j.poolMeta?.updatedAt||state.scanFinishedAt);return j}
async function tryUseSharedPool(from,trigger){let j=null;try{j=await api('/api/background/state',{},30000);if(j.build===BUILD&&j.cloudBackground===true){CLOUD_AUTO=j;await loadSharedPoolFromCloud(j.poolMeta,{allowStale:true})}}catch{}const meta=CLOUD_AUTO?.poolMeta||j?.poolMeta;if(!sharedPoolCovers(meta,from)||!state.rows.length)return false;const analysed=nearestRows(state.rows,from,Infinity,Date.now()).map(r=>analyze(r,from)).filter(Boolean).sort((a,b)=>Date.parse(a.date)-Date.parse(b.date));if(!analysed.length){if(!CLOUD_AUTO?.meta?.scanActive)void kickCloudRefresh('20-empty-cache');return false}state.pred=fillFromReserve(state.pred,from);const seen=new Set(state.pred.map(predKey));for(const p of analysed){if(state.pred.length>=20)break;const k=predKey(p);if(!seen.has(k)){seen.add(k);state.pred.push(p)}}state.pred.sort((a,b)=>Date.parse(a.date)-Date.parse(b.date));const chosen=new Set(state.pred.map(predKey));saveReserve([...analysed,...reserveLedger()].filter(p=>!chosen.has(predKey(p))).sort((a,b)=>Date.parse(a.date)-Date.parse(b.date)));state.scanComplete=meta?.complete===true;state.scanFinishedAt=Number(meta?.updatedAt||Date.now());markScanSuccess(trigger);if(trigger==='manual')await notifyCloudManualSuccess();else rememberPending(state.pred,'manual');render();const needsRefresh=!sharedPoolMetaFresh(meta)||meta?.complete!==true||analysed.length<20;if(needsRefresh)void kickCloudRefresh('20-cache-topup');setStatus('status',`✅ Lấy trực tiếp từ CACHE cloud ${Number(meta?.rowCount||state.rows.length)} row • không quét lại từ nguồn. Hiện ${state.pred.length}/20 trận.${needsRefresh?' Cloud đang tự bổ sung cache nền, không chặn màn hình.':''}`,true);return true}
async function syncCloudBackground(){if(SCAN_BUSY||BIG_BUSY||CHECK_BUSY)return CLOUD_AUTO;if(CLOUD_SYNC_BUSY)return CLOUD_SYNC_BUSY;CLOUD_SYNC_BUSY=syncCloudState();try{return await CLOUD_SYNC_BUSY}finally{CLOUD_SYNC_BUSY=null}}
