function recordMarketSnapshots(rows){try{const all=JSON.parse(localStorage.getItem(PROHIST)||'{}'),now=Date.now();for(const p of rows||[]){const k=ledgerKey(p),a=all[k]||[];a.push({t:now,ahLine:p.ah?.line,ahL:p.ah?.leftOdd,ahR:p.ah?.rightOdd,ouLine:p.ou?.line,ouL:p.ou?.leftOdd,ouR:p.ou?.rightOdd});all[k]=a.filter(x=>now-x.t<=8*3600e3).slice(-40)}localStorage.setItem(PROHIST,JSON.stringify(all))}catch{}}
