function teamKey(s){return cleanLabel(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\b(fc|cf|sc|afc|club|the|fk|sk|ac)\b/g,' ').replace(/[^a-z0-9]+/g,' ').trim()}
function bigramScore(a,b){a=teamKey(a).replace(/\s+/g,'');b=teamKey(b).replace(/\s+/g,'');if(!a||!b)return 0;if(a===b)return 1;if(a.includes(b)||b.includes(a))return .94;if(Math.min(a.length,b.length)<4)return 0;const grams=x=>{let m=new Map();for(let i=0;i<x.length-1;i++){let g=x.slice(i,i+2);m.set(g,(m.get(g)||0)+1)}return m},A=grams(a),B=grams(b);let hit=0,na=0,nb=0;for(const v of A.values())na+=v;for(const v of B.values())nb+=v;for(const [g,v] of A)hit+=Math.min(v,B.get(g)||0);return (2*hit)/Math.max(1,na+nb)}
function teamScore(q,name){const a=teamKey(q),b=teamKey(name);if(!a||!b)return 0;if(a===b)return 1;if(b.includes(a)||a.includes(b))return .97;const qa=a.split(/\s+/),bs=new Set(b.split(/\s+/));if(qa.length&&qa.every(x=>bs.has(x)))return .93;return bigramScore(a,b)}
