function updateModelCell(m,k,grade){const z=m[k]||{n:0,w:0};z.n+=Math.abs(grade);if(grade>0)z.w+=grade;m[k]=z}
async function checkSavedData(){const b=$('checkSaved');if(b)b.disabled=true;try{const j=await syncCloudState();const h=Array.isArray(j.history)?j.history.length:0,p=Array.isArray(j.pending)?j.pending.length:0,n=Array.isArray(j.predictions)?j.predictions.length:0,big=Array.isArray(j.featuredPredictions)?j.featuredPredictions.length:0;setStatus('savedStatus',`✅ Cloud đã lưu: ${n} dự đoán thường • ${big} trận lớn • ${p} trận chờ chấm • ${h} trận đã chấm.`,true);renderLearn();return j}catch(e){setStatus('savedStatus','❌ Không đọc được dữ liệu cloud đã lưu: '+e.message,false);throw e}finally{if(b)b.disabled=false}}
async function settleNow(){const b=$('settleNow');if(b)b.disabled=true;try{setStatus('savedStatus','⏳ Đang ép cập nhật và chấm các trận đã đủ giờ…');const j=await api('/api/background/settle-now',{method:'POST'},90000);if(j.ok===false)throw Error(j.error||'Chấm kết quả thất bại');if(j.state){CLOUD_AUTO=j.state;if(Array.isArray(j.state.history))localStorage.setItem(HIST,JSON.stringify(uniqueRecords(j.state.history)));if(Array.isArray(j.state.pending))localStorage.setItem(PENDING,JSON.stringify(mergePending(j.state.pending,[],j.state.history||[])));if(j.state.model&&typeof j.state.model==='object')localStorage.setItem(MODEL,JSON.stringify(j.state.model));if(j.state.methodLab&&typeof j.state.methodLab==='object')localStorage.setItem(METHODLAB,JSON.stringify(j.state.methodLab));}renderLearn();renderAutoStatus(`Vừa chấm thêm ${Number(j.settled||0)} trận.`);const left=Array.isArray(j.state?.pending)?j.state.pending.length:pendingLedger().length;setStatus('savedStatus',`✅ Chấm xong: thêm ${Number(j.settled||0)} trận • còn ${left} trận đang chờ/ chưa đủ điều kiện.`,true);return j}catch(e){setStatus('savedStatus','❌ Chấm kết quả lỗi: '+e.message,false);throw e}finally{if(b)b.disabled=false}}
async function settleOld(){return settleNow()}
function historyWindow(h,days){const cut=Date.now()-days*86400000;return h.filter(x=>Number(x.settledAt||Date.parse(x.date)||0)>=cut)}
function vnDayKey(ts){try{return DAY_VN.format(new Date(ts))}catch{return''}}
let LEARN_TIMER=null;
function scheduleLearn(){if(LEARN_TIMER!==null)return;LEARN_TIMER=setTimeout(()=>{LEARN_TIMER=null;try{renderLearn()}catch(e){setStatus('learn','Không đọc được thống kê: '+e.message,false)}},0)}
function renderLearn(){
 let h=[];try{h=JSON.parse(localStorage.getItem(HIST)||'[]')}catch{}
 h=uniqueRecords(h);const pending=mergePending(pendingLedger(),[],h), today=vnDayKey(Date.now()), yesterday=vnDayKey(Date.now()-86400000);
 const pendingDue=p=>{const t=Date.parse(p?.date);return Number.isFinite(t)&&Date.now()>=t+4*3600_000};
 const fmt=(rows,key,waitDue,waitEarly)=>{const x=marketGradeStats(rows,key),wait=waitDue+waitEarly;return `Tổng ${x.rows.length+wait} • thắng ${x.fullW} • thắng nửa ${x.halfW} • hòa ${x.push} • thua nửa ${x.halfL} • thua ${x.fullL} • chờ ghép KQ ${waitDue} • chưa đến giờ chấm ${waitEarly} • tỷ lệ quy đổi ${x.pct===null?'chưa có':x.pct.toFixed(1)+'%'}`};
 const report=(label,match)=>{const rows=h.filter(x=>match(vnDayKey(Date.parse(x.date)))),waiting=pending.filter(x=>match(vnDayKey(Date.parse(x.date)))),waitDue=waiting.filter(pendingDue).length,waitEarly=waiting.length-waitDue;return `${label}\nAH: ${fmt(rows,'ahGrade',waitDue,waitEarly)}\nTài/Xỉu: ${fmt(rows,'ouGrade',waitDue,waitEarly)}`};
 $('yesterday').textContent=report('HÔM QUA '+yesterday,d=>d===yesterday);
 const days=[...new Set([...h,...pending].map(x=>vnDayKey(Date.parse(x.date))))].sort().reverse();
 const months=[...new Set(days.map(d=>d.slice(0,7)))];
 $('learn').innerHTML='<p>Tự chấm từ khoảng 4 giờ sau giờ bắt đầu trận và thử lại mỗi 10 phút; trận chưa ghép được kết quả sẽ giữ chờ, không tính thua. Tỷ lệ quy đổi = (thắng + ½ thắng nửa) / (thắng + thua + ½ thắng nửa + ½ thua nửa); loại hòa. Ngày/tháng tính theo giờ bắt đầu trận tại Việt Nam.</p>'+ '<details open><summary>Thống kê tháng</summary><pre>'+esc(months.map(m=>report(m,d=>d.startsWith(m))).join('\n\n'))+'</pre></details><details><summary>Thống kê từng ngày</summary><pre>'+esc(days.map(d=>report(d,k=>k===d)).join('\n\n'))+'</pre></details><details><summary>Hiệu quả 15 phương pháp</summary>'+['AH','OU'].map(type=>'<h3>'+type+'</h3><p>Đang áp dụng: '+esc(METHOD_NAMES[methodLab().champion?.[type]||'book_weight'])+'</p>'+rankedMethods(type).map(x=>{const rec=methodLab()[type]?.[x.id],roi=roiSummary(rec),ev=rec?.events||[],z=marketGradeStats(ev.map(e=>({g:e.g})),'g');return '<p>'+esc(x.name)+': '+x.n+' mẫu • tỷ lệ quy đổi '+(z.pct===null?'chưa có':z.pct.toFixed(1)+'%')+' • ROI '+(roi.roi===null?'chưa đủ giá kèo':roi.roi.toFixed(1)+'% / '+roi.n+' mẫu')+(NEW_METHODS.includes(x.id)?(eligibleMethod(x.id,methodLab()[type])?' • đủ điều kiện tham gia':' • chấm thử, chưa tác động kèo chính'):'')+' • calibration '+(x.brier===null?'chưa có':x.brier.toFixed(3))+' • điểm xếp hạng '+(x.score*100).toFixed(1)+(x.n<20?' • chưa đủ 20 mẫu':'')+'</p>'}).join('')).join('')+'</details><p>Lần học gần nhất: '+esc(CLOUD_AUTO?.meta?.lastLearnAt?vnTime(CLOUD_AUTO.meta.lastLearnAt):'chưa có kết quả được chấm')+'. Phương pháp mới được chấm thử ít nhất 60 mẫu có giá kèo, phải hơn phương pháp gốc về điểm kết quả và ROI ở cả hai nửa thời gian mới được tham gia. Điểm xếp hạng không phải xác suất thắng. Tự học không bảo đảm dự đoán tốt hơn.</p>';
 const totals=ledgerTotals(h,pending),ackKeys=new Set([...(CLOUD_AUTO?.pending||[]),...(CLOUD_AUTO?.history||[])].map(ledgerKey)),unuploaded=pending.filter(p=>!ackKeys.has(ledgerKey(p))).length;
 const summary=document.createElement('p');summary.textContent=`Sổ kèo: ${totals.matches} trận / ${totals.matches*2} kèo (AH ${totals.AH.total}, Tài/Xỉu ${totals.OU.total}). Lấy tay: ${totals.manual}; trận lớn: ${totals.featured||0}; nền: ${totals.background}; dữ liệu cũ chưa rõ nguồn: ${totals.legacy}. Một trận có thể được lấy từ cả hai chế độ, chỉ chấm một lần. Chưa đồng bộ cloud: ${unuploaded} trận.`;$('learn').prepend(summary);
 const detail=document.createElement('details'),select=document.createElement('select'),list=document.createElement('div');detail.innerHTML='<summary>Chi tiết từng trận đã lấy và kết quả</summary>';for(const d of days){const o=document.createElement('option');o.value=d;o.textContent=d;select.append(o)}select.value=days.includes(yesterday)?yesterday:days[0]||'';
 const draw=()=>{list.innerHTML=[...h,...pending].filter(p=>vnDayKey(Date.parse(p.date))===select.value).sort((a,b)=>Date.parse(a.date)-Date.parse(b.date)).map((p,i)=>`<div class="fixture"><b>${i+1}. ${esc(cleanLabel(p.home))} — ${esc(cleanLabel(p.away))}</b><div>${esc(vnTime(p.date))} • ${esc(typeof p.score==='string'&&/^\d+-\d+$/.test(p.score)?p.score:'Chưa có kết quả')}</div><div>AH: ${esc(formatPick(p.ah||{type:'AH',pick:p.ahPick,line:p.ahLine},p))} — ${gradeName(p.ahGrade)}</div><div>Tài/Xỉu: ${esc(formatPick(p.ou||{type:'OU',pick:p.ouPick,line:p.ouLine},p))} — ${gradeName(p.ouGrade)}</div></div>`).join('')||'Chưa có trận';};select.onchange=draw;detail.append(select,list);$('learn').append(detail);draw();
 renderAutoStatus();
}
$('stopScan').onclick=stopScan;$('check').onclick=livecheck;$('scan').onclick=()=>scan(false,'manual');$('bigScan').onclick=scanBigMatches;$('copyBig').onclick=copyBig;if($('checkSaved'))$('checkSaved').onclick=()=>checkSavedData().catch(()=>{});if($('settleNow'))$('settleNow').onclick=()=>settleNow().catch(()=>{});if($('toggleBig'))$('toggleBig').onclick=()=>{const box=$('bigResults'),b=$('toggleBig'),hide=!box.classList.contains('hidden');box.classList.toggle('hidden',hide);b.textContent=hide?'MỞ 30 TRẬN':'THU GỌN'};$('copyAll').onclick=copyAll;$('find').onclick=findTeam;$('team').addEventListener('keydown',e=>{if(e.key==='Enter')findTeam()});document.querySelectorAll('[data-n]').forEach(b=>b.onclick=()=>showAcca(+b.dataset.n));if($('saveKeys'))$('saveKeys').onclick=()=>saveAllKeys();if($('toggleKeys'))$('toggleKeys').onclick=()=>{const box=$('keyBody'),b=$('toggleKeys'),hide=!box.classList.contains('hidden');box.classList.toggle('hidden',hide);b.textContent=hide?'HIỆN KEY':'ẨN KEY'};load();
